import java.util.*;
import java.io.*;

public class Main {
    static final long mod = 1000000007;
    static final long mod2 = 998244353;
    static List<Integer>[] pos = new ArrayList[10];
    static int cnt;
    static long[] pw = new long[15], s = new long[15];
    static long cnt2, n;
    static int ans;

    static {
        for (int i = 0; i < 10; i++) {
            pos[i] = new ArrayList<>();
        }
    }

    static int query(int fixpre, long val) {
        long ans = 0;
        for (int d = 0; d < 7; d++) {
            long offset = (val - fixpre * pw[d]) % mod2;
            if (offset < 0) offset += mod2;
            int p = lowerBound(pos[d], (int)(mod2 - offset));
            ans = (ans + s[d] + offset * pos[d].size() - mod2 * (pos[d].size() - p)) % mod;
        }
        return (int) ans;
    }

    static int lowerBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    static void dfs(int val, int d) {
        int x = (cnt - val + (int) mod2) % (int) mod2;
        pos[d].add(x);
        cnt++;
        s[d] += x;
        if (d == 6) return;
        for (int i = 0; i < 10; i++) {
            dfs(val * 10 + i, d + 1);
        }
    }

    static void dfs2(long val) {
        if (val * 1000000 + 999999 <= n && val * 10000000 > n) {
            ans = (ans + query((int) val, cnt2 + 1)) % (int) mod;
            cnt2 += cnt;
        } else {
            cnt2++;
            ans = (ans + ((cnt2 - val) % mod2 + mod2) % mod2) % (int) mod;
            int start = val != 0 ? 0 : 1;
            for (int i = start; i < 10; i++) {
                if (val * 10 + i <= n) {
                    dfs2(val * 10 + i);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        for (int i = 0; i < 10; i++) {
            pos[i] = new ArrayList<>();
        }
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        n = Long.parseLong(line);
        cnt2 = -1;
        cnt = 0;
        s = new long[7];
        pw[0] = 1;
        for (int i = 1; i < 13; i++) {
            pw[i] = pw[i - 1] * 10;
        }
        dfs(0, 0);
        for (int i = 0; i < 7; i++) {
            Collections.sort(pos[i]);
        }
        ans = 0;
        dfs2(0);
        System.out.println(ans);
    }
}
